import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function isDateText(v: unknown): v is string {
  return typeof v === 'string' && DATE_RE.test(v);
}

function isId(v: unknown): boolean {
  const ok = typeof v === 'number' || (typeof v === 'string' && v.trim() !== '');
  return ok && Number.isInteger(Number(v)) && Number(v) > 0;
}

@Controller('api/v1')
export class FnSfr00702Controller {
  @Post('/tax-invoices/collect')
  @HttpCode(200)
  async collectTaxInvoices(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    if (!isDateText(data['fromDate']) || !isDateText(data['toDate'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수집 시작일과 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (data['fromDate'] > data['toDate']) {
      throw new ApiError(400, 'VALIDATION_FAILED', '수집 시작일은 종료일보다 늦을 수 없습니다.');
    }
    return transaction(async (db) => {
      // 가정: 홈택스 연계 클라이언트가 제공되지 않아, 연계로 반영된 전자세금계산서 중 기간 내 건수를 수집 건수로 센다.
      const rows = await db.query(
        'SELECT COUNT(*) AS "collectedCount" FROM tax_invoice WHERE issue_date >= CAST(:fromDate AS date) AND issue_date <= CAST(:toDate AS date)',
        { fromDate: data['fromDate'], toDate: data['toDate'] },
      );
      return { collectedCount: Number(rows[0]['collectedCount']) };
    });
  }

  @Post('/tax-invoices/:taxInvoiceId/create-resolution')
  @HttpCode(200)
  async createTaxInvoiceResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const taxInvoiceId = req.params['taxInvoiceId'];
    const data = checks.inputOf(req.body);
    if (!isId(taxInvoiceId)) {
      throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '전자세금계산서를 찾을 수 없습니다.');
    }
    if (data['taxType'] !== '과세' && data['taxType'] !== '면세') {
      throw new ApiError(400, 'VALIDATION_FAILED', '과세·면세 구분을 선택해 주세요.');
    }
    if (data['resolutionType'] !== '지출' && data['resolutionType'] !== '수입') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결의 유형을 선택해 주세요.');
    }
    if (!isDateText(data['resolutionDate'])) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결의일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const idLabels: [string, string][] = [
      ['partnerId', '거래처'],
      ['departmentId', '결의부서'],
      ['projectId', '프로젝트'],
      ['budgetItemId', '예산과목'],
    ];
    for (const [key, label] of idLabels) {
      if (!isId(data[key])) {
        throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 선택해 주세요.');
      }
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT tax_invoice_id, expense_resolution_id, reconciliation_result, supply_amount, tax_amount FROM tax_invoice WHERE tax_invoice_id = CAST(:id AS bigint) FOR UPDATE',
        { id: taxInvoiceId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '전자세금계산서를 찾을 수 없습니다.');
      }
      const invoice = found[0];
      if (invoice['expense_resolution_id'] !== null && invoice['expense_resolution_id'] !== undefined) {
        throw new ApiError(409, 'TAX_INVOICE_RESOLUTION_DUPLICATED', '이미 결의서가 작성된 전자세금계산서입니다.');
      }
      if (invoice['reconciliation_result'] !== '일치') {
        throw new ApiError(422, 'TAX_INVOICE_RECONCILIATION_MISMATCH', '대사 결과가 일치인 전자세금계산서만 결의서를 작성할 수 있습니다.');
      }
      const amount = Number(invoice['supply_amount']) + Number(invoice['tax_amount']);
      if (!(amount > 0)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결의 금액은 0보다 커야 합니다.');
      }
      const refs: [string, string, string, string][] = [
        ['partner', 'partner_id', 'partnerId', '거래처'],
        ['department', 'department_id', 'departmentId', '결의부서'],
        ['project', 'project_id', 'projectId', '프로젝트'],
        ['budget_item', 'budget_item_id', 'budgetItemId', '예산과목'],
      ];
      for (const [table, column, key, label] of refs) {
        const exists = await db.query(
          'SELECT 1 AS ok FROM ' + table + ' WHERE ' + column + ' = CAST(:v AS bigint)',
          { v: data[key] },
        );
        if (exists.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', label + '을(를) 찾을 수 없습니다.');
        }
      }
      const created = await db.query(
        'INSERT INTO expense_resolution (resolution_date, department_id, author_id, resolution_type, project_id, budget_item_id, partner_id, amount, evidence_type, approval_status, created_at, updated_at) ' +
          'VALUES (CAST(:resolutionDate AS date), CAST(:departmentId AS bigint), CAST(:userId AS bigint), :resolutionType, CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:partnerId AS bigint), CAST(:amount AS numeric), :evidenceType, :approvalStatus, now(), now()) ' +
          'RETURNING expense_resolution_id',
        {
          resolutionDate: data['resolutionDate'],
          departmentId: data['departmentId'],
          userId: user.id,
          resolutionType: data['resolutionType'],
          projectId: data['projectId'],
          budgetItemId: data['budgetItemId'],
          partnerId: data['partnerId'],
          amount: amount,
          evidenceType: '전자세금계산서',
          approvalStatus: '기안',
        },
      );
      const resolutionId = Number(created[0]['expense_resolution_id']);
      // 가정: 문서번호는 결의서 ID로 자동 채번한다.
      await db.execute(
        "UPDATE expense_resolution SET document_no = 'ER-' || lpad(CAST(:id AS text), 8, '0'), updated_at = now() WHERE expense_resolution_id = CAST(:id AS bigint)",
        { id: resolutionId },
      );
      await db.execute(
        'UPDATE tax_invoice SET expense_resolution_id = CAST(:rid AS bigint), tax_type = :taxType, updated_at = now() WHERE tax_invoice_id = CAST(:id AS bigint)',
        { rid: resolutionId, taxType: data['taxType'], id: taxInvoiceId },
      );
      return { expenseResolutionId: resolutionId };
    });
  }
}

