import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pager,
  RefName,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

export default function FnSfr00702Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [partnerFilter, setPartnerFilter] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [collectOpen, setCollectOpen] = useState(false);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [target, setTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({});

  const list = useData<Page>(
    () => call<Page>('GET', '/tax-invoices', role, undefined, { ...applied, page, size: 20 }),
    [applied, page, role],
  );
  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;

  const search = () => {
    setPage(0);
    setApplied({ startDate, endDate, partnerId: partnerFilter });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setPartnerFilter('');
    setPage(0);
    setApplied({});
  };

  const set = (key: string, value: unknown) => setForm((prev) => ({ ...prev, [key]: value }));

  const openResolution = (row: Row) => {
    setTarget(row);
    setForm({
      taxType: row['taxType'],
      partnerId: row['partnerId'],
      resolutionType: row['direction'] === '매출' ? '수입' : '지출',
    });
  };

  const submitCollect = async () => {
    if (!fromDate || !toDate) {
      throw new Error('수집 시작일과 종료일을 입력해 주세요.');
    }
    const result = await call<Row>('POST', '/tax-invoices/collect', role, { fromDate, toDate });
    notify('전자세금계산서 ' + String(result['collectedCount']) + '건을 수집했습니다.');
    setCollectOpen(false);
    list.reload();
  };

  const submitResolution = async () => {
    if (!target) return;
    const required: [string, string][] = [
      ['taxType', '과세·면세 구분'],
      ['partnerId', '거래처'],
      ['resolutionDate', '결의일자'],
      ['departmentId', '결의부서'],
      ['projectId', '프로젝트'],
      ['budgetItemId', '예산과목'],
      ['resolutionType', '결의 유형'],
    ];
    for (const [key, label] of required) {
      if (form[key] === undefined || form[key] === null || form[key] === '') {
        throw new Error(label + '을(를) 입력해 주세요.');
      }
    }
    await call('POST', '/tax-invoices/' + String(target['taxInvoiceId']) + '/create-resolution', role, form);
    notify('결의서를 작성했습니다.');
    setTarget(null);
    list.reload();
  };

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>수집 현황</h2>
        <Tiles items={[['조회된 전자세금계산서', <Num value={total} />]]} />
      </section>
      <section className='box span-12'>
        <h2>전자세금계산서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='발행일 시작'>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label='발행일 종료'>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label='거래처 ID'>
            <LookupSelect table='partner' role={role} value={partnerFilter} onChange={setPartnerFilter} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={() => setCollectOpen(true)}>
            홈택스 수집
          </button>
        </Band>
        <DataTable
          rows={rows}
          empty='전자세금계산서가 없습니다.'
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            {
              key: 'partnerId',
              label: '거래처 ID',
              render: (r) => <RefName table='partner' role={role} value={r['partnerId']} />,
            },
            { key: 'direction', label: '매출/매입 구분', render: (r) => <Badge value={r['direction']} /> },
            { key: 'taxType', label: '과세·면세 구분' },
            { key: 'issueDate', label: '작성일자', render: (r) => <DateText value={r['issueDate']} /> },
            { key: 'supplyAmount', label: '공급가액', render: (r) => <Num value={r['supplyAmount']} /> },
            { key: 'taxAmount', label: '세액', render: (r) => <Num value={r['taxAmount']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (
                <button type='button' onClick={() => openResolution(r)}>
                  결의서 작성
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>
      {collectOpen && (
        <Drawer title='홈택스 전자세금계산서 수집' onClose={() => setCollectOpen(false)}>
          <Form onSubmit={submitCollect} submit='수집'>
            <Field label='수집 시작일' required>
              <DateInput value={fromDate} onChange={setFromDate} />
            </Field>
            <Field label='수집 종료일' required>
              <DateInput value={toDate} onChange={setToDate} />
            </Field>
          </Form>
        </Drawer>
      )}
      {target && (
        <Drawer title='전자세금계산서 결의서 작성' onClose={() => setTarget(null)}>
          <Form onSubmit={submitResolution} submit='결의서 작성'>
            <Field label='과세·면세 구분' required>
              <Select
                value={form['taxType']}
                onChange={(v) => set('taxType', v)}
                options={[['과세', '과세'], ['면세', '면세']]}
              />
            </Field>
            <Field label='거래처' required>
              <LookupSelect table='partner' role={role} value={form['partnerId']} onChange={(v) => set('partnerId', v)} />
            </Field>
            <Field label='결의일자' required>
              <DateInput value={form['resolutionDate']} onChange={(v) => set('resolutionDate', v)} />
            </Field>
            <Field label='결의부서' required>
              <LookupSelect table='department' role={role} value={form['departmentId']} onChange={(v) => set('departmentId', v)} />
            </Field>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={form['projectId']} onChange={(v) => set('projectId', v)} />
            </Field>
            <Field label='예산과목' required>
              <LookupSelect table='budget_item' role={role} value={form['budgetItemId']} onChange={(v) => set('budgetItemId', v)} />
            </Field>
            <Field label='결의 유형' required>
              <Select
                value={form['resolutionType']}
                onChange={(v) => set('resolutionType', v)}
                options={[['지출', '지출'], ['수입', '수입']]}
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
